package api

// The replay's winner table is generated by the independent B1 evaluator.
// It consumes request-specification state, never actual ELF replay output.
import (
	"encoding/json"
	"fmt"
	"github.com/littlewolf9527/xdrop/node/agent/eval"
	"net/netip"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"testing"
)

type cut56ReplayOracleRule struct {
	ID           string  `json:"id"`
	LogicalID    uint32  `json:"logical_id"`
	SrcIP        string  `json:"src_ip"`
	DstIP        string  `json:"dst_ip"`
	SrcCIDR      string  `json:"src_cidr"`
	DstCIDR      string  `json:"dst_cidr"`
	SrcPort      uint16  `json:"src_port"`
	DstPort      uint16  `json:"dst_port"`
	Protocol     string  `json:"protocol"`
	Action       string  `json:"action"`
	RateLimit    uint32  `json:"rate_limit"`
	TcpFlags     string  `json:"tcp_flags"`
	MatchAnomaly uint8   `json:"match_anomaly"`
	PktLenMin    uint16  `json:"pkt_len_min"`
	PktLenMax    uint16  `json:"pkt_len_max"`
	TTL          *string `json:"ttl"`
	DSCP         *string `json:"dscp"`
	ICMPType     *string `json:"icmp_type"`
	ICMPCode     *string `json:"icmp_code"`
	Fragment     *string `json:"fragment"`
	PktLen       *string `json:"pkt_len"`
}

func cut56ReplayOracleSet(t *testing.T, tables eval.Tables, rules []cut56ReplayOracleRule) eval.B1RuleSet {
	t.Helper()
	rs := eval.B1RuleSet{}
	srcs, dsts := map[string]uint32{}, map[string]uint32{}
	counts := map[string]int{}
	identity := func(r cut56ReplayOracleRule) string {
		return fmt.Sprintf("%s/%s/%s/%s/%d/%d/%s", r.SrcIP, r.DstIP, r.SrcCIDR, r.DstCIDR, r.SrcPort, r.DstPort, r.Protocol)
	}
	for _, r := range rules {
		counts[identity(r)]++
	}
	proto := map[string]uint8{"": 0, "all": 0, "tcp": 6, "udp": 17, "icmp": 1, "icmpv6": 58}
	for _, r := range rules {
		v := eval.B1Rule{Rule: eval.Rule{ID: r.ID, Conditions: eval.Conditions{MinLength: r.PktLenMin, MaxLength: r.PktLenMax, Anomaly: r.MatchAnomaly}}, LogicalID: r.LogicalID, TTL: r.TTL, DSCP: r.DSCP, ICMPType: r.ICMPType, ICMPCode: r.ICMPCode, Fragment: r.Fragment, PktLen: r.PktLen}
		v.HasConditions = counts[identity(r)] > 1 || r.TTL != nil || r.DSCP != nil || r.ICMPType != nil || r.ICMPCode != nil || r.Fragment != nil || r.PktLen != nil || r.TcpFlags != "" || r.PktLenMin > 0 || (r.PktLenMax != 0 && r.PktLenMax != 65535) || r.MatchAnomaly != 0
		if r.Action == "rate_limit" {
			v.Rate = r.RateLimit
		}
		for _, word := range strings.Split(r.TcpFlags, ",") {
			word = strings.TrimSpace(word)
			negative := strings.HasPrefix(word, "!")
			word = strings.TrimPrefix(word, "!")
			for bit, name := range []string{"FIN", "SYN", "RST", "PSH", "ACK", "URG", "ECE", "CWR"} {
				if word == name {
					v.FlagsMask |= 1 << bit
					if !negative {
						v.FlagsValue |= 1 << bit
					}
				}
			}
		}
		mask := eval.Mask(0)
		if r.SrcIP != "" || r.SrcCIDR != "" {
			mask |= eval.SrcIP
		}
		if r.DstIP != "" || r.DstCIDR != "" {
			mask |= eval.DstIP
		}
		if r.SrcPort != 0 {
			mask |= eval.SrcPort
		}
		if r.DstPort != 0 {
			mask |= eval.DstPort
		}
		if proto[r.Protocol] != 0 {
			mask |= eval.Protocol
		}
		combo := -1
		for _, n := range tables.Order {
			if tables.Masks[n] == mask {
				combo = n
				break
			}
		}
		if combo < 0 {
			t.Fatalf("oracle rule has no combo: %+v", r)
		}
		if r.SrcCIDR != "" || r.DstCIDR != "" {
			if r.SrcCIDR != "" {
				if srcs[r.SrcCIDR] == 0 {
					srcs[r.SrcCIDR] = uint32(len(srcs) + 1)
					rs.SrcPrefixes = append(rs.SrcPrefixes, eval.Prefix{Network: netip.MustParsePrefix(r.SrcCIDR), ID: srcs[r.SrcCIDR]})
				}
				v.CIDRKey.SrcID = srcs[r.SrcCIDR]
			}
			if r.DstCIDR != "" {
				if dsts[r.DstCIDR] == 0 {
					dsts[r.DstCIDR] = uint32(len(dsts) + 1)
					rs.DstPrefixes = append(rs.DstPrefixes, eval.Prefix{Network: netip.MustParsePrefix(r.DstCIDR), ID: dsts[r.DstCIDR]})
				}
				v.CIDRKey.DstID = dsts[r.DstCIDR]
			}
			v.CIDRKey.Sport, v.CIDRKey.Dport, v.CIDRKey.Proto = r.SrcPort, r.DstPort, proto[r.Protocol]
			rs.CIDR = append(rs.CIDR, v)
			rs.CIDRBitmap |= 1 << combo
		} else {
			if r.SrcIP != "" {
				v.Key.Src = netip.MustParseAddr(r.SrcIP)
			}
			if r.DstIP != "" {
				v.Key.Dst = netip.MustParseAddr(r.DstIP)
			}
			v.Key.Sport, v.Key.Dport, v.Key.Proto = r.SrcPort, r.DstPort, proto[r.Protocol]
			rs.Exact = append(rs.Exact, v)
			rs.ExactBitmap |= 1 << combo
		}
	}
	return rs
}
func cut56ReplayOraclePacket(name string) eval.B1Packet {
	p := eval.B1Packet{Packet: eval.Packet{Tuple: eval.Tuple{Src: netip.MustParseAddr("192.0.2.1"), Dst: netip.MustParseAddr("198.51.100.1"), Sport: 1234, Dport: 80, Proto: 6}, Length: 40, Flags: 2}, TTL: 64}
	switch name {
	case "miss":
		p.Src = netip.MustParseAddr("203.0.113.1")
	case "ack":
		p.Flags = 16
	case "length400":
		p.Length = 400
	case "bad_fragment":
		p.Anomaly = 1
		p.FragClass = 2
	case "invalid_tcp":
		p.Anomaly = 2
		p.Flags = 0
	case "icmp_zero":
		p.Proto = 1
		p.Sport = 0
		p.Dport = 0
		p.Flags = 0
		p.ICMPValid = true
	case "length_mismatch":
		p.Length = 60
		p.Anomaly = 4
	case "length_mismatch_ack":
		p.Length, p.Anomaly, p.Flags = 60, 4, 16
	case "offset_one":
		p.Anomaly = 8
		p.NonFirst = true
		p.FragClass = 1
		p.Flags = 0
	case "syn", "rate":
	default:
		panic("unknown oracle packet " + name)
	}
	return p
}
func TestCut56ReplayOracle(t *testing.T) {
	input := os.Getenv("XDROP_CUT56_ORACLE_INPUT")
	if input == "" {
		return
	} // Optional artifact emission; normal oracle grid has no environment dependency.
	var cases map[string]struct {
		RulesP5, RulesP6 []cut56ReplayOracleRule
		Packets          []string
	}
	raw, err := os.ReadFile(input)
	if err != nil {
		t.Fatal(err)
	}
	if err = json.Unmarshal(raw, &cases); err != nil {
		t.Fatal(err)
	}
	root := os.Getenv("XDROP_B1_ROOT")
	if root == "" {
		root, err = filepath.Abs("../../..")
		if err != nil {
			t.Fatal(err)
		}
	}
	tables, err := eval.LoadTables(root, eval.B1)
	if err != nil {
		t.Fatal(err)
	}
	out := map[string]map[string][]eval.B1Decision{}
	names := make([]string, 0, len(cases))
	for name := range cases {
		names = append(names, name)
	}
	sort.Strings(names)
	cells := 0
	for _, name := range names {
		fixture := cases[name]
		out[name] = map[string][]eval.B1Decision{"P5": {}, "P6": {}}
		for _, version := range []string{"P5", "P6"} {
			rules := fixture.RulesP5
			if version == "P6" {
				rules = fixture.RulesP6
			}
			// B1 H validates identities even for pure rows. The protocol-3-only
			// zero-ID API fixture uses a private oracle identity; selection is then
			// projected back to its requested zero ID, with no change to rule intent.
			zero := map[string]bool{}
			rules = append([]cut56ReplayOracleRule(nil), rules...)
			for i := range rules {
				if rules[i].LogicalID == 0 {
					zero[rules[i].ID] = true
					rules[i].LogicalID = 0xffff0000 + uint32(i+1)
				}
			}
			set := cut56ReplayOracleSet(t, tables, rules)
			for _, packet := range fixture.Packets {
				predict := eval.EvaluateB1Cut54
				d, e := predict(tables, set, cut56ReplayOraclePacket(packet))
				if e != nil {
					t.Fatalf("%s %s: %v", name, version, e)
				}
				if zero[d.RuleID] {
					d.LogicalID = 0
				}
				out[name][version] = append(out[name][version], d)
				cells++
			}
		}
	}
	raw, err = json.MarshalIndent(out, "", "  ")
	if err != nil {
		t.Fatal(err)
	}
	if err = os.WriteFile(os.Getenv("XDROP_CUT56_ORACLE_OUT"), append(raw, '\n'), 0600); err != nil {
		t.Fatal(err)
	}
	t.Logf("CUT56_REPLAY_ORACLE cases=%d packet_predictions=%d source=independent_B1_generations ELF_observations=0", len(cases), cells)
}
